#!/usr/bin/env bash
# CPU serving benchmark for KVShrink: raw / sw / qat connector arms and vLLM's own prefix cache.
#
# The load is generated by `vllm bench serve` with the same client settings as
# tests/vllm-benchmark.sh (random dataset, shared prefix = hit rate, --ignore-eos,
# --request-rate inf), so CPU and GPU numbers come from the same client. Per point:
#   1. prime:   send the same prompts cut to prefix + 1 token, so only the shared prefix is cached
#   2. settle:  wait until the connector has finished writing the cache
#   3. measure: the real prompts; vLLM's own prefix-cache counters confirm the achieved hit rate
#
# Every input is an environment variable; lists are space separated. Examples:
#   MODEL=/models/Qwen3-8B benchmark/kvstore/serving_benchmark.sh
#   MODEL=/models/Qwen3-8B ARMS="raw qat" INPUT_LENS=8192 OUTPUT_LENS=8 HIT_RATES=100 \
#       CONCURRENCY="1 4 16" benchmark/kvstore/serving_benchmark.sh
#   # GPU (or any already running server): label the run with the arm it serves.
#   SERVER=external PORT=8000 ARMS=qat MODEL=Qwen/Qwen3-32B benchmark/kvstore/serving_benchmark.sh
set -euo pipefail

# ---- Inputs ----------------------------------------------------------------------------------
MODEL="${MODEL:?set MODEL to the model path or ID the server loads}"
ARMS="${ARMS:-raw sw qat vllm}"         # raw | sw | qat | vllm (vLLM prefix cache, no connector)
INPUT_LENS="${INPUT_LENS:-8192}"        # prompt tokens
OUTPUT_LENS="${OUTPUT_LENS:-128}"       # generated tokens
HIT_RATES="${HIT_RATES:-80}"            # % of each prompt shared with the other prompts
CONCURRENCY="${CONCURRENCY:-1 4 16}"    # concurrent clients per point
PROMPTS_PER_CLIENT="${PROMPTS_PER_CLIENT:-2}"
MIN_PROMPTS="${MIN_PROMPTS:-8}"
BLOCK_SIZE="${BLOCK_SIZE:-32}"
SEED="${SEED:-20260925}"
SERVER="${SERVER:-launch}"              # launch: start one CPU server per cell and arm; external: use PORT
PORT="${PORT:-8000}"
SERVER_CPUS="${SERVER_CPUS:-0-31}"      # server cores; the launcher keeps the last IAXL_CORES for IAXL
CLIENT_CPUS="${CLIENT_CPUS:-}"          # cores for the load generator, outside SERVER_CPUS
NUMA_NODE="${NUMA_NODE:-0}"
IAXL_CORES="${IAXL_CORES:-2}"
CACHE_POOL_GB="${CACHE_POOL_GB:-96}"
RESULTS="${RESULTS:-$PWD/results/serving-$(date +%Y%m%d-%H%M%S)}"

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
WORKER_API_PORT="${IAXL_API_WORKER_BASE_PORT:-18800}"
SUMMARY="$RESULTS/summary.csv"
SERVER_PGID=""

log() { echo "[$(date +%H:%M:%S)] $*" >&2; }
die() { log "ERROR: $*"; exit 1; }

# ---- Server ----------------------------------------------------------------------------------
arm_env() {
    case "$1" in
        raw)  echo "IAXL_KV_COMPRESSION=0 IAXL_QAT_ZIP_ENABLE=0 IAXL_CPU_ZIP_ENABLE=0" ;;
        sw)   echo "IAXL_KV_COMPRESSION=1 IAXL_QAT_ZIP_ENABLE=0 IAXL_CPU_ZIP_ENABLE=1 IAXL_CPU_ZIP_THREADS=$IAXL_CORES" ;;
        qat)  echo "IAXL_KV_COMPRESSION=1 IAXL_QAT_ZIP_ENABLE=1 IAXL_CPU_ZIP_ENABLE=0" ;;
        vllm) echo "KVSHRINK_CONNECTOR=0" ;;
        *)    die "unknown arm '$1' (expected raw, sw, qat or vllm)" ;;
    esac
}

start_server() {  # arm input_len output_len max_concurrency dir
    local arm=$1 input_len=$2 output_len=$3 max_c=$4 dir=$5
    [[ "$SERVER" == "external" ]] && return 0
    local kv_gib=$(( input_len * BYTES_PER_TOKEN * max_c / 1024 ** 3 + 6 ))
    log "start $arm server (input=$input_len output=$output_len kv=${kv_gib}GiB)"
    # The launcher derives inference/IAXL core sets from the CPUs numactl leaves visible.
    env -u OMP_NUM_THREADS -u VLLM_CPU_OMP_THREADS_BIND -u IAXL_CPU_AFFINITY \
        $(arm_env "$arm") MODEL="$MODEL" PORT="$PORT" BLOCK_SIZE="$BLOCK_SIZE" \
        IAXL_CORES="$IAXL_CORES" IAXL_CACHE_DIR="$dir/cache" IAXL_DDR_POOL_SIZE_GB="$CACHE_POOL_GB" \
        MAX_MODEL_LEN=$(( input_len + output_len + 64 )) MAX_NUM_SEQS="$max_c" \
        VLLM_CPU_KVCACHE_SPACE="$kv_gib" HF_HUB_OFFLINE=1 \
        setsid numactl --all --physcpubind="$SERVER_CPUS" --membind="$NUMA_NODE" \
        "$REPO/examples/kvshrink-vllm-cpu-serve.sh" \
        --max-num-batched-tokens $(( input_len > 8192 ? input_len : 8192 )) \
        > "$dir/server.log" 2>&1 &
    SERVER_PGID=$!
    for _ in $(seq 900); do
        curl -sf "http://127.0.0.1:$PORT/v1/models" > /dev/null && return 0
        kill -0 "$SERVER_PGID" 2> /dev/null || die "$arm server exited; see $dir/server.log"
        sleep 1
    done
    die "$arm server not ready after 900 s; see $dir/server.log"
}

stop_server() {
    [[ -z "$SERVER_PGID" ]] && return 0
    kill -TERM -- "-$SERVER_PGID" 2> /dev/null || true
    for _ in $(seq 60); do kill -0 "$SERVER_PGID" 2> /dev/null || break; sleep 1; done
    kill -KILL -- "-$SERVER_PGID" 2> /dev/null || true
    SERVER_PGID=""
}
trap stop_server EXIT INT TERM

# ---- Measurements ----------------------------------------------------------------------------
metric() {  # sum of a vLLM Prometheus counter over all label sets
    curl -sf "http://127.0.0.1:$PORT/metrics" | awk -v name="$1" '$1 ~ "^"name"(\\{|$)" { s += $2 } END { printf "%.0f", s }'
}

settle_cache_writes() {  # the connector saves asynchronously; wait until its put count stops moving
    local status="http://127.0.0.1:$WORKER_API_PORT/v1/cache/status" last=-1 still=0 puts
    curl -sf "$status" > /dev/null || return 0
    for _ in $(seq 900); do
        puts=$(curl -sf "$status" | jq '.puts')
        if [[ "$puts" == "$last" ]]; then (( ++still >= 3 )) && return 0; else still=0; last=$puts; fi
        sleep 1
    done
    die "cache writes did not settle"
}

qat_requests() {  # QAT firmware request counter; empty when debugfs is not readable
    cat /sys/kernel/debug/qat_*/fw_counters 2> /dev/null |
        awk '/^[[:space:]]*[0-9]+:[[:space:]]+[0-9]+[[:space:]]+[0-9]+[[:space:]]*$/ { s += $2; n++ }
             END { if (n) print s }'
}

bench() {  # seed prompts suffix_len output_len concurrency prefix_len [extra args]
    local seed=$1 prompts=$2 suffix=$3 output=$4 conc=$5 prefix=$6; shift 6
    local client=()
    [[ -n "$CLIENT_CPUS" ]] && client=(taskset -c "$CLIENT_CPUS")
    "${client[@]}" vllm bench serve \
        --backend vllm --model "$MODEL" --tokenizer "$MODEL" --host 127.0.0.1 --port "$PORT" \
        --dataset-name random --random-prefix-len "$prefix" --random-input-len "$suffix" \
        --random-output-len "$output" --ignore-eos --seed "$seed" \
        --num-prompts "$prompts" --max-concurrency "$conc" --request-rate inf \
        --num-warmups 0 --percentile-metrics ttft,tpot,itl,e2el --metric-percentiles 50,95,99 \
        --disable-tqdm "$@"
}

run_point() {  # arm input_len output_len hit_rate concurrency dir
    local arm=$1 input_len=$2 output_len=$3 hit=$4 conc=$5 dir=$6
    local prefix=$(( input_len * hit / 100 / BLOCK_SIZE * BLOCK_SIZE ))
    (( prefix >= input_len )) && prefix=$(( input_len - BLOCK_SIZE ))
    local suffix=$(( input_len - prefix ))
    local prompts=$(( conc * PROMPTS_PER_CLIENT > MIN_PROMPTS ? conc * PROMPTS_PER_CLIENT : MIN_PROMPTS ))
    local seed=$(( SEED + input_len * 1000 + hit * 10 + conc ))
    local name="in${input_len}-out${output_len}-hit${hit}-c${conc}"
    local hits=vllm:external_prefix_cache_hits_total queries=vllm:external_prefix_cache_queries_total
    [[ "$arm" == "vllm" ]] && hits=vllm:prefix_cache_hits_total queries=vllm:prefix_cache_queries_total

    # Same seed and prompt count reproduce the same shared prefix; a 1-token suffix caches only it.
    log "$arm $name: prime prefix ($prefix tokens)"
    bench "$seed" "$prompts" 1 1 1 "$prefix" > "$dir/$name.prime.log" 2>&1 ||
        die "priming failed; see $dir/$name.prime.log"
    settle_cache_writes

    local hits0 queries0 qat0
    hits0=$(metric "$hits"); queries0=$(metric "$queries"); qat0=$(qat_requests)
    log "$arm $name: measure ($prompts prompts, concurrency $conc)"
    bench "$seed" "$prompts" "$suffix" "$output_len" "$conc" "$prefix" \
        --save-result --result-dir "$dir" --result-filename "$name.json" \
        --metadata "arm=$arm" "hit_rate=$hit" "prefix_len=$prefix" \
        > "$dir/$name.log" 2>&1 || die "benchmark failed; see $dir/$name.log"
    settle_cache_writes

    local hit_pct qat_delta="n/a" dsa="off"
    hit_pct=$(awk -v h=$(( $(metric "$hits") - hits0 )) -v q=$(( $(metric "$queries") - queries0 )) \
        'BEGIN { printf "%.1f", q ? 100 * h / q : 0 }')
    [[ -n "$qat0" ]] && qat_delta=$(( $(qat_requests) - qat0 ))
    if [[ -f "$dir/server.log" ]]; then
        grep -q "falling back to CPU memcpy" "$dir/server.log" && dsa="fallback"
        grep -q "using Intel DSA" "$dir/server.log" && [[ "$dsa" == "off" ]] && dsa="on"
    fi
    jq -r --arg arm "$arm" --arg in "$input_len" --arg out "$output_len" --arg hit "$hit" \
          --arg c "$conc" --arg meas "$hit_pct" --arg qat "$qat_delta" --arg dsa "$dsa" \
        'def r(d): (. * pow(10; d) | round) / pow(10; d);
         [$arm, $in, $out, $hit, $c, .completed, .failed // 0, (.request_throughput | r(3)),
          (.output_throughput | r(1)), (.median_ttft_ms | r(1)), (.p95_ttft_ms | r(1)),
          (.median_tpot_ms | r(1)), (.p95_tpot_ms | r(1)),
          $meas, $qat, $dsa] | map(tostring) | join(",")' "$dir/$name.json" >> "$SUMMARY"
    tail -n 1 "$SUMMARY" >&2
}

# ---- Main ------------------------------------------------------------------------------------
for tool in vllm curl jq numactl taskset setsid; do
    command -v "$tool" > /dev/null || die "$tool not found (activate the vLLM environment first)"
done
for arm in $ARMS; do arm_env "$arm" > /dev/null; done
if [[ "$SERVER" == "launch" ]]; then
    curl -sf "http://127.0.0.1:$PORT/v1/models" > /dev/null && die "port $PORT already serves a model"
    pgrep -f "vllm serve|vllm.entrypoints" > /dev/null && die "another vLLM server is running; stop it first"
    CONFIG="$MODEL/config.json"
    [[ -f "$CONFIG" ]] || die "$CONFIG not found; MODEL must be a local model directory"
    BYTES_PER_TOKEN=$(jq '2 * .num_hidden_layers * .num_key_value_heads
                          * (.head_dim // (.hidden_size / .num_attention_heads)) * 2' "$CONFIG")
elif [[ "$SERVER" == "external" ]]; then
    curl -sf "http://127.0.0.1:$PORT/v1/models" > /dev/null || die "no server on port $PORT"
else
    die "SERVER must be launch or external"
fi

mkdir -p "$RESULTS"
echo "arm,input_len,output_len,hit_rate,concurrency,completed,failed,req_per_s,output_tok_per_s,ttft_median_ms,ttft_p95_ms,tpot_median_ms,tpot_p95_ms,measured_hit_pct,qat_requests,dsa" > "$SUMMARY"
max_c=$(tr ' ' '\n' <<< "$CONCURRENCY" | sort -n | tail -n 1)
log "results: $RESULTS"

cell=0
for input_len in $INPUT_LENS; do
    for output_len in $OUTPUT_LENS; do
        for hit in $HIT_RATES; do
            arms=($ARMS)
            # Alternate arm order between cells so slow machine drift cancels out.
            (( cell++ % 2 )) && arms=($(printf '%s\n' "${arms[@]}" | tac))
            for arm in "${arms[@]}"; do
                dir="$RESULTS/in${input_len}-out${output_len}-hit${hit}-$arm"
                mkdir -p "$dir"
                start_server "$arm" "$input_len" "$output_len" "$max_c" "$dir"
                for conc in $CONCURRENCY; do
                    run_point "$arm" "$input_len" "$output_len" "$hit" "$conc" "$dir"
                done
                stop_server
            done
        done
    done
done

log "done: $SUMMARY"
column -s, -t < "$SUMMARY"
